FROM loads l
JOIN trips t ON l.load_id = t.load_id;

WITH miles AS (
 SELECT SUM(actual_distance_miles) AS total_miles
 FROM trips
), faults AS (
 SELECT COUNT(*) AS fault_count
 FROM safety_incidents
 WHERE at_fault_flag = true
)
SELECT (faults.fault_count / NULLIF(miles.total_miles,0)) * 1000000 AS at_fault_rate_per_million_miles
FROM faults, miles;

WITH rev AS (
 SELECT SUM(l.revenue) AS total_revenue
 FROM loads l
), dist AS (
 SELECT SUM(t.actual_distance_miles) AS total_distance
 FROM trips t
)
SELECT rev.total_revenue / NULLIF(dist.total_distance, 0) AS revenue_per_mile
FROM rev, dist;
